const C=window.FOCO_CONFIG||{};
const configured=Boolean(C.supabaseUrl&&C.publishableKey);
const qs=(sel)=>document.querySelector(sel);
const app=qs('#app');
const storeKey='foco_pmmg_session_v1';
const demoKey='foco_pmmg_demo_v1';
const subj=[
 {name:'Português',short:'Português',ico:'book',weight:20},
 {name:'Direito e Direitos Humanos',short:'Direito e D. Humanos',ico:'shield',weight:10},
 {name:'Raciocínio Lógico-Matemático',short:'Raciocínio Lógico',ico:'brain',weight:10},
 {name:'Inglês',short:'Inglês',ico:'language',weight:5},
 {name:'Literatura',short:'Literatura',ico:'library',weight:5}];
const paths={shield:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/><path d="m9 12 2 2 4-4"/>',book:'<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2Z"/>',brain:'<path d="M12 18V5a3 3 0 0 0-5.5-1.6A4 4 0 0 0 4 10a4 4 0 0 0 1 7 3 3 0 0 0 6 2"/><path d="M12 18V5a3 3 0 0 1 5.5-1.6A4 4 0 0 1 20 10a4 4 0 0 1-1 7 3 3 0 0 1-6 2"/>',language:'<path d="m5 8 6 6m-7 0 6-6 2-3H2m8-3v3m3 16 5-11 5 11m-8-4h6"/>',library:'<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2Z"/><path d="M8 7h8M8 11h7"/>',home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1Z"/><path d="M9 21v-8h6v8"/>',bolt:'<path d="m13 2-3 8H4l9 12 1-9h6Z"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',chart:'<path d="M3 3v18h18"/><path d="m7 15 4-4 4 3 5-7"/>',crown:'<path d="m2 7 5 5 5-8 5 8 5-5-2 12H4Z"/>',logout:'<path d="M10 17l5-5-5-5m5 5H3"/><path d="M13 3h5a3 3 0 0 1 3 3v12a3 3 0 0 1-3 3h-5"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.9m-3-12a4 4 0 0 1 0 7.8"/>',check:'<path d="m5 12 4 4L19 6"/>',bookmark:'<path d="M5 4a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2v18l-7-4-7 4Z"/>',flame:'<path d="M12 22c5 0 8-4 8-8 0-3-2-6-4-8 0 4-3 5-3 5s2-6-4-9c1 6-5 8-5 14 0 4 3 6 8 6Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',back:'<path d="m15 18-6-6 6-6"/>',arrow:'<path d="m5 12 14 0m-6-6 6 6-6 6"/>',award:'<circle cx="12" cy="8" r="6"/><path d="m8 13-2 9 6-3 6 3-2-9"/>',settings:'<path d="M12 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z"/><path d="M20 12a8 8 0 0 0-.2-1.8l2-1.5-2-3.4-2.3.9A8 8 0 0 0 14 4.2L13.6 2h-4l-.4 2.2A8 8 0 0 0 6.5 6.2l-2.3-.9-2 3.4 2 1.5a8 8 0 0 0 0 3.6l-2 1.5 2 3.4 2.3-.9a8 8 0 0 0 2.7 2l.4 2.2h4l.4-2.2a8 8 0 0 0 2.7-2l2.3.9 2-3.4-2-1.5c.1-.6.2-1.2.2-1.8Z"/>',alert:'<path d="M12 3 2 21h20Z"/><path d="M12 9v5m0 3h.01"/>',spark:'<path d="m12 3 1.8 6.2L20 11l-6.2 1.8L12 19l-1.8-6.2L4 11l6.2-1.8Z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>'};
function ic(n,size=20){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[n]||paths.shield}</svg>`}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function fmtDate(d){return new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(d))}
function first(s){return(s||'Candidato').trim().split(/\s+/)[0]}
const choose=(a)=>a[Math.floor(Math.random()*a.length)];
let state={screen:'login',user:null,profile:null,session:null,demo:false,demoAdmin:false,questions:[],attempts:[],bookmarks:[],reports:[],people:[],allAttempts:[],adminDetail:null,training:null,loading:false,remember:true};
let timer=null;let selection=null;
const officialExams=window.FOCO_EXAMS||[];let officialSession=null;let officialResultData=null;let officialRuns=[];
function toast(msg){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.textContent=msg;document.body.appendChild(el);setTimeout(()=>el.remove(),3200)}
function progressOf(attempts){const unique=new Set(attempts.map(a=>a.question_id));const correct=attempts.filter(a=>a.correct).length;const today=fmtDate(new Date());const todayCount=attempts.filter(a=>fmtDate(a.created_at)===today).length;const dates=new Set(attempts.map(a=>fmtDate(a.created_at)));let streak=0;let date=new Date();if(!dates.has(fmtDate(date)))date.setDate(date.getDate()-1);for(let i=0;i<365;i++){if(!dates.has(fmtDate(date)))break;streak++;date.setDate(date.getDate()-1)}const by={};for(const s of subj){const xs=attempts.filter(a=>a.subject===s.name);by[s.name]={total:xs.length,correct:xs.filter(a=>a.correct).length,pct:xs.length?Math.round(xs.filter(a=>a.correct).length/xs.length*100):0}}return {total:attempts.length,unique:unique.size,correct,rate:attempts.length?Math.round(correct/attempts.length*100):0,xp:attempts.reduce((n,a)=>n+(a.xp||0),0),todayCount,streak,by}}
function backendHeaders(token){return {'apikey':C.publishableKey,'Content-Type':'application/json',...(token?{'Authorization':'Bearer '+token}:{})}}
async function req(path,options={},auth=true,retry=true){const url=C.supabaseUrl.replace(/\/$/,'')+path;const init={...options,headers:{...backendHeaders(auth?state.session?.access_token:null),...options.headers}};let res=await fetch(url,init);if(res.status===401&&auth&&retry&&state.session?.refresh_token){await refreshSession();return req(path,options,auth,false)}if(!res.ok){let info;try{info=await res.json()}catch{info={}}throw Error(info.msg||info.message||info.error_description||info.error||`Erro HTTP ${res.status}`)}if(res.status===204)return null;const raw=await res.text();return raw?JSON.parse(raw):null}
function saveSession(session,remember=state.remember){const obj={...session,expires_at:session.expires_at||Math.floor(Date.now()/1000)+(session.expires_in||3600),remember};if(remember){localStorage.setItem(storeKey,JSON.stringify(obj));sessionStorage.removeItem(storeKey)}else{sessionStorage.setItem(storeKey,JSON.stringify(obj));localStorage.removeItem(storeKey)}state.session=obj;state.remember=remember}
async function refreshSession(){const cur=state.session;if(!cur?.refresh_token)throw Error('Sessão expirada');const s=await req('/auth/v1/token?grant_type=refresh_token',{method:'POST',body:JSON.stringify({refresh_token:cur.refresh_token})},false,false);saveSession(s,cur.remember);state.user=s.user;return s}
async function login(email,password,remember){const s=await req('/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({email,password})},false,false);saveSession(s,remember);state.user=s.user;state.demo=false;if(!['admin','student'].includes(s.user?.app_metadata?.role)){localStorage.removeItem(storeKey);sessionStorage.removeItem(storeKey);state.session=null;state.user=null;throw Error('Sua conta ainda não foi autorizada pelo administrador.')}await loadProfileAndData();state.screen=state.profile?.onboarded?'home':'welcome';render()}
async function loadProfileAndData(){const p=await req(`/rest/v1/profiles?select=*&user_id=eq.${state.user.id}`);state.profile=p[0]||null;const [questions,attempts,marks]=await Promise.all([req('/rest/v1/questions?select=*&is_active=eq.true&order=id.asc&limit=2000'),req('/rest/v1/attempts?select=*&order=created_at.desc&limit=20000'),req('/rest/v1/bookmarks?select=question_id')]);state.questions=questions.map(q=>({id:q.id,subject:q.subject,topic:q.topic,origin:q.origin,sourceLabel:q.source_label,year:q.year,stem:q.stem,options:q.options,answer:q.answer,explanation:q.explanation,difficulty:q.difficulty,book:q.book,reviewStatus:q.review_status}));state.attempts=attempts;state.bookmarks=marks.map(x=>x.question_id);officialRuns=await req('/rest/v1/official_exam_results?select=*&order=created_at.desc&limit=300');if(isAdmin())await loadAdminData()}
async function loadAdminData(){[state.people,state.allAttempts,state.reports]=await Promise.all([req('/rest/v1/profiles?select=*&order=created_at.asc'),req('/rest/v1/attempts?select=*&order=created_at.desc&limit=20000'),req('/rest/v1/reports?select=*&order=created_at.desc')]);state.officialAdminRuns=await req('/rest/v1/official_exam_results?select=*&order=created_at.desc&limit=10000')}
function isAdmin(){return state.demo?Boolean(state.demoAdmin):state.user?.app_metadata?.role==='admin'}
async function saveName(name){name=name.trim().slice(0,60);if(name.length<2)throw Error('Informe um nome com pelo menos 2 caracteres.');if(!state.demo){await req('/rest/v1/profiles?user_id=eq.'+state.user.id,{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify({display_name:name,onboarded:true})})}else{localStorage.setItem('foco_demo_name',name)}state.profile={...(state.profile||{}),display_name:name,onboarded:true};state.screen='home';render()}
async function startDemo(){state.demo=true;state.demoAdmin=true;state.user={id:'demo',email:'visitante@demo.local',app_metadata:{role:'admin'}};state.profile={display_name:localStorage.getItem('foco_demo_name')||'Visitante'};state.attempts=JSON.parse(localStorage.getItem(demoKey)||'[]');try{const embedded=document.querySelector('#questions-inline');if(embedded?.textContent){state.questions=JSON.parse(embedded.textContent)}else{let r=await fetch('./data/questions.json');if(!r.ok)r=await fetch('./assets/sample-questions.json');if(!r.ok)throw Error('Não foi possível carregar as questões');state.questions=await r.json()}}catch(e){toast('Não foi possível carregar o banco local. Abra pelo servidor web.');state.questions=[]}state.bookmarks=JSON.parse(localStorage.getItem('foco_demo_bookmarks')||'[]');state.people=[{user_id:'demo',display_name:state.profile.display_name+' (prévia)',email:'visita@exemplo.invalid'}];state.allAttempts=state.attempts;state.reports=[];officialRuns=JSON.parse(localStorage.getItem('foco_simulados_demo_results')||'[]');state.officialAdminRuns=officialRuns;state.screen='home';render()}
function logout(){officialSession=null;officialResultData=null;officialRuns=[];state={...state,session:null,user:null,profile:null,demo:false,demoAdmin:false,screen:'login',questions:[],attempts:[],bookmarks:[],training:null};localStorage.removeItem(storeKey);sessionStorage.removeItem(storeKey);render()}
function switchScreen(screen){if(screen==='admin'&&!isAdmin())return;state.screen=screen;render();window.scrollTo({top:0,behavior:'smooth'})}
function badge(t,cls=''){return `<span class="tag ${cls}">${esc(t)}</span>`}
function ring(n){return `<div class="ring" style="--val:${Math.max(0,Math.min(100,n))}"><span>${n}%</span></div>`}
function btn(t,fn,cls='primary'){return `<button class="btn ${cls}" data-action="${fn}">${t}</button>`}
function navlist(){let items=[['home','Início','home'],['train','Treinar','bolt'],['subjects','Disciplinas','book'],['simulados','Simulados oficiais','calendar'],['review','Revisar erros','target'],['stats','Meu radar','chart']];if(isAdmin())items.push(['admin','Administração','users']);return items}
function shell(content){let p=progressOf(state.attempts),name=first(state.profile?.display_name);return `<div class="shell"><aside class="sidebar"><div class="logo"><span class="brandmark">${ic('shield',23)}</span><div><div class="brand">FOCO <b>PMMG</b></div><div class="micro">Operação 2027</div></div></div><div class="nav">${navlist().map(([id,label,icon])=>`<button data-action="nav:${id}" class="${state.screen===id?'active':''}">${ic(icon,19)} ${esc(label)}</button>`).join('')}</div><div class="sidebar-bottom stack"><div class="pill">${ic('flame',16)} <span>${p.streak} dia${p.streak===1?'':'s'} de sequência</span></div><div class="profilechip"><span class="avatar">${esc(name[0]||'C')}</span><span style="flex:1;min-width:0"><b>${esc(name)}</b><br><span class="muted tiny">${isAdmin()?'Administrador':state.demo?'Prévia local':'Estudante'}</span></span><button class="btn outline sm" title="Sair" data-action="logout">${ic('logout',17)}</button></div></div></aside><main class="main enter"><div class="topline"><div class="row"><span class="eyebrow">FOCO PMMG 2027</span>${state.demo?badge('MODO PRÉVIA','gold-tag'):''}</div><div class="pill">${ic('award',17)} <b class="gold">${p.xp} XP</b></div></div>${content}</main><div class="bottomnav">${navlist().filter(([id])=>['home','train','simulados','review','stats'].includes(id)).map(([id,label,icon])=>`<button data-action="nav:${id}" class="${state.screen===id?'active':''}">${ic(icon,21)}<span>${esc(label)}</span></button>`).join('')}${isAdmin()?`<button data-action="nav:admin" class="${state.screen==='admin'?'active':''}">${ic('users',21)}<span>Admin</span></button>`:''}</div></div>`}
const motivation=['Sua aprovação começa com a questão de hoje.','O hábito vence a empolgação passageira.','Quem mantém o foco transforma esforço em resultado.','Um dia de cada vez. Uma questão por vez.','Sua disciplina é o seu diferencial.','Continue. Seu futuro agradece.'];
function home(){let p=progressOf(state.attempts),name=first(state.profile?.display_name);let period=new Date().getHours()<12?'Bom dia':new Date().getHours()<18?'Boa tarde':'Boa noite';let daily=Math.min(p.todayCount,10);return shell(`<div class="dashboard"><section class="hero"><div class="micro">Sua missão continua</div><h1>${period}, ${esc(name)}.<br><span class="gold">É hora de evoluir.</span></h1><p>${esc(choose(motivation))} Treine em qualquer pausa do dia, acompanhe seus acertos e fortaleça o que ainda precisa melhorar.</p><div class="buttons">${btn(ic('bolt',19)+' Iniciar treino rápido','nav:train')}${btn(ic('chart',18)+' Meu desempenho','nav:stats','ghost')}${btn(ic('calendar',18)+' Provas oficiais','nav:simulados','ghost')}</div></section>
${state.demo?`<div class="banner-warning">${ic('alert',16)} Esta é uma prévia local sem login real nem sincronização. Os resultados ficam neste navegador. Para compartilhar com amigos, configure um projeto Supabase exclusivo.</div>`:''}
<section class="grid g3"><div class="card stat">${ic('award',23)}<div class="number">${p.xp.toLocaleString('pt-BR')}</div><div class="muted">Pontos conquistados</div></div><div class="card stat">${ic('target',23)}<div class="number">${p.rate}%</div><div class="muted">Taxa de acertos</div></div><div class="card stat">${ic('flame',23)}<div class="number">${p.streak}</div><div class="muted">Dias consecutivos</div></div></section>
<section class="grid g2"><div class="card stack"><div class="row between"><div class="stack-tight"><div class="micro">Sua missão diária</div><h2 class="subhead">10 questões hoje</h2></div><span class="pill">${daily}/10</span></div><div class="progress"><div style="width:${daily*10}%"></div></div><div class="muted small">${daily===10?'Missão de hoje concluída. Parabéns!':`Faltam ${10-daily} questões para conquistar sua missão.`}</div>${btn(ic('bolt',17)+' Resolver agora','nav:train','primary full')}</div>
<div class="card stack"><div class="row between"><div><div class="micro">Acervo inicial</div><h2 class="subhead">Banco de questões</h2></div>${ic('book',26)}</div><div class="row between"><div class="number" style="font-size:38px;font-weight:800">${state.questions.length}</div>${badge('100 / matéria','gold-tag')}</div><div class="muted small">Questões autorais em revisão editorial, com explicações e marcação de origem. Provas originais da PMMG estão disponíveis em Simulados Oficiais. Literatura geral provisória, sem livros antigos.</div>${btn('Explorar disciplinas '+ic('arrow',15),'nav:subjects','outline full')}</div></section>
<section><div class="section-title"><h2>Seu radar de conhecimento</h2><button class="btn outline sm" data-action="nav:stats">Ver detalhes ${ic('arrow',15)}</button></div><div class="subject-grid">${subj.map(s=>`<div class="subject-card"><div class="subject-icon">${ic(s.ico,18)}</div><div class="subject-meta"><strong>${esc(s.short)}</strong><p>${p.by[s.name].total} respostas registradas</p></div>${ring(p.by[s.name].pct)}</div>`).join('')}</div></section><div class="card stack"><div class="row"><span class="gold">${ic('spark',19)}</span><b>Uma meta clara. Uma rotina possível.</b></div><p class="muted small">Seu radar mostra a precisão por disciplina, não uma promessa de aprovação. Mais importante que a pontuação é entender os erros e aumentar sua consistência.</p></div></div>`)}
function train(){let total=selection?.total||10,subject=selection?.subject||'Todas as matérias',mode=selection?.mode||'inteligente';return shell(`<div class="train-layout stack"><div><div class="eyebrow">PLANEJAMENTO DE MISSÃO</div><h1 class="headline" style="margin:10px 0">Treino rápido</h1><p class="muted">Escolha o foco, o número de questões e comece em segundos.</p></div><div class="card stack"><h3>Quantidade de questões</h3><div class="row wrap">${[5,10,20,50].map(n=>`<button class="btn ${n===total?'primary':'outline'}" data-action="total:${n}" style="flex:1">${n}</button>`).join('')}</div><div class="muted tiny">Em 50 questões, o modo simulado respeita os pesos do edital de referência.</div></div><div class="card stack"><h3>Disciplina</h3><div class="subject-select">${['Todas as matérias',...subj.map(s=>s.name)].map(s=>`<button class="mode-btn ${s===subject?'active':''}" data-action="subject:${esc(s)}">${esc(s)}</button>`).join('')}</div></div><div class="card stack"><h3>Modo de estudo</h3><div class="mode-grid">${[['inteligente','Inteligente','Reforça matérias mais difíceis'],['novas','Ainda não respondidas','Explore o banco sem repetir'],['erros','Revisão de erros','Volte ao que você errou'],['aleatorio','Aleatório','Questões misturadas']].map(([id,title,sub])=>`<button class="mode-btn ${id===mode?'active':''}" data-action="mode:${id}"><b>${title}</b><small>${sub}</small></button>`).join('')}</div></div><div class="banner-info">${ic('clock',16)} Sem relógio obrigatório: você decide seu ritmo. Progresso e revisão são personalizados para cada usuário.</div>${btn(ic('bolt',18)+` Começar ${total} questões`,'begin','primary full')}</div>`)}
function getWrongIds(){const last=new Map();for(const a of [...state.attempts].reverse())last.set(a.question_id,a);return [...last.entries()].filter(([,a])=>!a.correct).map(([id])=>id)}
function generateQueue(){const config={total:selection?.total||10,subject:selection?.subject||'Todas as matérias',mode:selection?.mode||'inteligente'};let arr=state.questions.filter(q=>config.subject==='Todas as matérias'||q.subject===config.subject);const tried=new Set(state.attempts.map(a=>a.question_id));const wrong=new Set(getWrongIds());if(config.mode==='novas')arr=arr.filter(q=>!tried.has(q.id));if(config.mode==='erros')arr=arr.filter(q=>wrong.has(q.id));if(!arr.length){toast(config.mode==='erros'?'Você ainda não possui erros para revisar.':'Não há questões disponíveis com esses filtros.');return null}let byScore=progressOf(state.attempts).by;let sorted=[...arr].sort((a,b)=>{if(config.mode==='aleatorio'||config.mode==='erros')return Math.random()-.5;const A=(byScore[a.subject]?.pct||0),B=(byScore[b.subject]?.pct||0);const na=tried.has(a.id)?1:0,nb=tried.has(b.id)?1:0;return (na-nb)*100+((A||50)-(B||50))*0.5+(Math.random()-.5)*20});if(config.total===50&&config.subject==='Todas as matérias'&&config.mode!=='erros'){sorted=[];for(const s of subj){let xs=arr.filter(q=>q.subject===s.name).sort(()=>Math.random()-.5);sorted.push(...xs.slice(0,s.weight))}sorted.sort(()=>Math.random()-.5)}return sorted.slice(0,config.total)}
function begin(){const queue=generateQueue();if(!queue)return;state.training={queue,index:0,selected:null,confirmed:false,correct:0,earned:0,started:Date.now()};state.screen='question';render()}
function question(){const t=state.training;if(!t)return home();const q=t.queue[t.index];if(!q)return result();const progress=(t.index)/t.queue.length*100;return shell(`<div class="train-layout stack"><div class="row between"><button class="btn outline sm" data-action="end">${ic('back',16)} Encerrar</button><span class="pill">${ic('clock',16)} Questão ${t.index+1} de ${t.queue.length}</span></div><div class="progress"><div style="width:${progress}%"></div></div><div class="card stack question-card"><div class="question-head"><span class="question-source">${esc(q.sourceLabel||'Autoral · Foco PMMG 2027')}${q.origin==='real'?' · '+esc(q.year):''}</span>${badge(q.difficulty||'Média')}</div><div class="row between wrap"><span class="pill">${esc(q.subject)}</span><span class="muted tiny">${esc(q.topic||'Geral')}</span></div><div class="qtext">${esc(q.stem)}</div><div class="stack">${q.options.map((o,i)=>`<button class="optioncard ${t.selected===i?'chosen':''} ${t.confirmed&&i===q.answer?'correct':''} ${t.confirmed&&i===t.selected&&i!==q.answer?'wrong':''}" data-action="answer:${i}" ${t.confirmed?'disabled':''}><span class="letter">${'ABCD'[i]}</span><span>${esc(o)}</span>${t.confirmed&&i===q.answer?ic('check',18):''}</button>`).join('')}</div>${t.confirmed?`<div class="feedback ${t.selected===q.answer?'':'incorrect'}"><h3>${t.selected===q.answer?`✓ Resposta correta! ${t.lastXP?`+${t.lastXP} XP`:''}`:'✕ Vamos aprender com esse erro'}</h3><p><b>Gabarito: ${'ABCD'[q.answer]}.</b> ${esc(q.explanation)}</p>${q.reviewStatus==='revisao_editorial'?`<p class="tiny" style="margin-top:8px;color:#d5bd8e">Questão autoral em revisão editorial.</p>`:''}</div>`:''}<div class="row wrap">${t.confirmed?btn(`Próxima questão ${ic('arrow',17)}`,'next','primary full'):`<button class="btn primary full" data-action="confirm" ${t.selected===null?'disabled':''}>Confirmar resposta</button>`}</div><div class="row between wrap"><button class="btn outline sm" data-action="bookmark:${q.id}">${ic('bookmark',16)} ${state.bookmarks.includes(q.id)?'Salva':'Salvar'}</button><button class="btn outline sm" data-action="report:${q.id}">${ic('alert',16)} Reportar problema</button></div></div></div>`)}
async function confirm(){
 const t=state.training;if(!t||t.selected===null||t.confirmed)return;
 const q=t.queue[t.index];let a;let answered;
 if(state.demo){
   answered=t.selected===q.answer;
   const past=state.attempts.filter(x=>x.question_id===q.id);
   const xp=answered&&!past.some(x=>x.correct)?10+(past.some(x=>!x.correct)?4:0):0;
   a={id:crypto.randomUUID(),user_id:state.user.id,question_id:q.id,subject:q.subject,topic:q.topic,correct:answered,selected:t.selected,xp,created_at:new Date().toISOString()};
   state.attempts.unshift(a);localStorage.setItem(demoKey,JSON.stringify(state.attempts));
 }else{
   const res=await req('/rest/v1/rpc/submit_answer',{method:'POST',body:JSON.stringify({p_question_id:q.id,p_selected:t.selected})});
   a=res.attempt;answered=a.correct;q.answer=res.answer;q.explanation=res.explanation;
   state.attempts.unshift(a);
 }
 t.confirmed=true;t.lastXP=a.xp;t.earned+=a.xp;t.correct+=answered?1:0;render();
}
function next(){const t=state.training;if(t.index>=t.queue.length-1){state.screen='result'}else{t.index++;t.selected=null;t.confirmed=false;t.lastXP=0}render()}
function result(){let t=state.training||{queue:[],correct:0,earned:0};let pct=t.queue.length?Math.round(t.correct/t.queue.length*100):0;return shell(`<div class="train-layout stack"><div class="card stack" style="align-items:center;text-align:center;padding:36px 25px"><div style="color:var(--gold)" class="sparkle">${ic('award',60)}</div><div class="micro">Missão concluída</div><h1 class="headline">Você avançou mais um passo!</h1><p class="muted">O progresso acontece quando você aparece e faz a sua parte.</p><div class="grid g3" style="width:100%;margin-top:16px"><div><div class="number" style="font-size:29px;font-weight:800">${t.correct}/${t.queue.length}</div><div class="muted tiny">Acertos</div></div><div><div class="number" style="font-size:29px;font-weight:800">${pct}%</div><div class="muted tiny">Precisão</div></div><div><div class="number gold" style="font-size:29px;font-weight:800">+${t.earned}</div><div class="muted tiny">XP conquistado</div></div></div></div><div class="card stack"><h3>Seu próximo passo</h3><p class="muted small">Confira as disciplinas com menor percentual de acertos e revise as perguntas que errou. Erros são oportunidades de aprendizado.</p>${btn(ic('target',18)+' Revisar minhas dificuldades','nav:review','primary full')}${btn('Novo treino','nav:train','ghost full')}${btn('Voltar ao painel','nav:home','outline full')}</div></div>`)}
function subjects(){const p=progressOf(state.attempts);return shell(`<div class="stack"><div><div class="eyebrow">CONHEÇA SEUS PONTOS FORTES</div><h1 class="headline" style="margin:10px 0">Disciplinas</h1><p class="muted">100 questões autorais iniciais em cada área, divididas por assuntos.</p></div><div class="subject-grid">${subj.map(s=>{const n=state.questions.filter(q=>q.subject===s.name).length;const topics=new Set(state.questions.filter(q=>q.subject===s.name).map(q=>q.topic)).size;const x=p.by[s.name];return `<div class="card stack"><div class="row between"><div class="subject-icon">${ic(s.ico,22)}</div>${ring(x.pct)}</div><h3 style="font-size:18px">${esc(s.name)}</h3><div class="muted small">${n} questões · ${topics} assuntos · ${x.total} respostas</div><div class="progress"><div style="width:${x.pct}%"></div></div><button class="btn primary full" data-action="practice:${esc(s.name)}">Praticar disciplina ${ic('arrow',17)}</button></div>`}).join('')}</div></div>`)}
function review(){let wrongs=getWrongIds();const saved=state.bookmarks;let q=state.questions.filter(x=>wrongs.includes(x.id)||saved.includes(x.id));return shell(`<div class="stack"><div class="eyebrow">REPETIR • ENTENDER • SUPERAR</div><h1 class="headline">Caderno de revisão</h1><p class="muted">Questões erradas e salvas permanecem aqui até você dominá-las.</p><div class="grid g3"><div class="card stat"><div class="number">${wrongs.length}</div><div class="muted">Erros pendentes</div></div><div class="card stat"><div class="number">${saved.length}</div><div class="muted">Salvas</div></div><div class="card stat"><div class="number">${q.length}</div><div class="muted">Na revisão</div></div></div>${q.length?`<div class="card stack">${q.slice(0,10).map(x=>`<div class="mission"><div class="stack-tight"><b>${esc(x.subject)}</b><span class="muted tiny">${esc(x.topic)} · ${esc(x.id)}</span></div><button class="btn outline sm" data-action="single:${x.id}">Resolver ${ic('arrow',15)}</button></div>`).join('')}</div>${btn('Iniciar revisão de erros','start-errors','primary full')}`:`<div class="card stack"><div class="subhead">Seu caderno ainda está vazio.</div><p class="muted">Faça o primeiro treino e suas dúvidas aparecerão aqui automaticamente.</p>${btn('Começar a praticar','nav:train','primary')}</div>`}</div>`)}
function radar(){let p=progressOf(state.attempts);const angles=subj.map((_,i)=>-Math.PI/2+i*Math.PI*2/5);const coords=(vals,scale)=>vals.map((v,i)=>`${(160+Math.cos(angles[i])*112*v*scale).toFixed(1)},${(160+Math.sin(angles[i])*112*v*scale).toFixed(1)}`).join(' ');const vals=subj.map(s=>p.by[s.name].total?p.by[s.name].pct/100:0);return shell(`<div class="stack"><div class="eyebrow">INTELIGÊNCIA DE ESTUDOS</div><h1 class="headline">Seu radar de conhecimento</h1><p class="muted">Acompanhe a precisão de cada disciplina e defina sua próxima prioridade.</p><div class="grid g2"><div class="card" style="text-align:center"><svg viewBox="0 0 320 320" width="100%" style="max-width:340px" role="img" aria-label="Radar de desempenho por disciplina">${[.25,.5,.75,1].map(a=>`<polygon points="${coords([a,a,a,a,a],1)}" fill="none" stroke="#466278" stroke-width="1"/>`).join('')}${angles.map(a=>`<line x1="160" y1="160" x2="${160+Math.cos(a)*112}" y2="${160+Math.sin(a)*112}" stroke="#466278"/>`).join('')}<polygon points="${coords(vals,1)}" fill="rgba(96,210,192,.22)" stroke="#6ad8ca" stroke-width="2"/>${angles.map((a,i)=>`<text x="${160+Math.cos(a)*143}" y="${164+Math.sin(a)*143}" font-size="10" fill="#bfccda" text-anchor="middle">${['Português','Direito','Matemática','Inglês','Literatura'][i]}</text>`).join('')}</svg><div class="muted tiny">Indicador de acertos, não estimativa de aprovação.</div></div><div class="card stack"><h3>Detalhamento por disciplina</h3>${subj.map(s=>{const x=p.by[s.name];return `<div class="stack-tight"><div class="row between"><span class="small">${esc(s.short)}</span><b>${x.total?x.pct+'%':'Sem dados'}</b></div><div class="progress"><div style="width:${x.pct}%"></div></div><div class="muted tiny">${x.correct} acertos de ${x.total} respostas</div></div>`}).join('')}</div></div><div class="card stack"><div class="row">${ic('chart',22)} <h3>Como usar seu radar</h3></div><p class="muted small">Estude primeiro as matérias com menor precisão, mas continue praticando todas. As taxas são baseadas nas respostas registradas, inclusive revisões; não representam sua nota prevista.</p>${btn('Treinar uma matéria','nav:train','primary')}</div></div>`)}
function admin(){if(!isAdmin())return shell('<div class="card">Acesso restrito.</div>');const people=state.people||[];const all=state.allAttempts||[];const reports=state.reports||[];return shell(`<div class="stack"><div class="eyebrow">ACESSO EXCLUSIVO DO ADMINISTRADOR</div><h1 class="headline">Central de comando</h1><p class="muted">Gerencie os estudantes, acompanhe a evolução e revise possíveis problemas do acervo.</p><div class="grid g3"><div class="card stat">${ic('users',22)}<div class="number">${people.length}</div><div class="muted">Usuários</div></div><div class="card stat">${ic('book',22)}<div class="number">${state.questions.length}</div><div class="muted">Questões no banco</div></div><div class="card stat">${ic('target',22)}<div class="number">${all.length}</div><div class="muted">Respostas registradas</div></div></div><div class="banner-info">${ic('calendar',17)} <b>${(state.officialAdminRuns||[]).length}</b> simulados oficiais registrados por estudantes.</div><div class="grid g2"><div class="card stack"><h3>Criar novo acesso</h3>${state.demo?`<div class="banner-warning">Exibição de demonstração: criação de usuários disponível apenas quando o backend seguro estiver conectado.</div>`:''}<p class="muted tiny">Somente contas criadas por você. Não existe cadastro público.</p><form id="create-user" class="stack"><div class="field"><label>Nome do estudante</label><input name="name" required minlength="2" placeholder="Nome completo"></div><div class="field"><label>E-mail de acesso</label><input name="email" type="email" required placeholder="aluno@exemplo.com"></div><div class="field"><label>Senha provisória</label><input name="password" type="password" required minlength="12" placeholder="Mínimo de 12 caracteres"></div><button class="btn primary full" type="submit" ${state.demo?'disabled':''}>${ic('users',17)} Criar usuário</button></form><div class="banner-info">Use a função segura do Supabase para criar contas. A senha nunca será enviada para o GitHub.</div></div><div class="card stack"><h3>Qualidade do conteúdo</h3><p class="muted small">Todas as 500 questões iniciais são autorais, com revisão pedagógica pendente. O painel registra relatos para que você possa corrigir gabaritos e enunciados.</p><div class="row between"><span>Relatos recebidos</span><b>${reports.length}</b></div>${reports.length?reports.slice(0,8).map(r=>`<div class="subject-card stack-tight" style="display:block"><b>${esc(r.question_id)}</b><div class="muted small">${esc(r.details)}</div><div class="tiny gold">${esc(r.status||'aberto')}</div></div>`).join(''):'<div class="muted small">Nenhum relato recebido até agora.</div>'}</div></div><div class="card stack"><h3>Progresso por usuário</h3><div class="table-wrap"><table class="table"><thead><tr><th>Estudante</th><th>Respostas</th><th>Acertos</th><th>Precisão</th><th>XP</th><th>Último treino</th><th>Simulados</th><th>Detalhes</th><th>Conta</th></tr></thead><tbody>${people.map(p=>{let as=all.filter(a=>a.user_id===p.user_id),x=progressOf(as);let last=as.length?fmtDate(as[0].created_at):'—';return `<tr><td><b>${esc(p.display_name||'Sem nome')}</b><div class="tiny muted">${esc(p.email||'')}</div></td><td>${x.total}</td><td>${x.correct}</td><td>${x.rate}%</td><td>${x.xp}</td><td>${last}</td><td>${(state.officialAdminRuns||[]).filter(r=>r.user_id===p.user_id).length}</td><td><button class="btn outline sm" data-action="detail:${p.user_id}">Ver radar</button></td><td><button class="btn outline sm" data-action="${p.disabled?'enable':'disable'}:${p.user_id}" ${state.demo||p.user_id===state.user.id?'disabled':''}>${p.disabled?'Reativar':'Desativar'}</button></td></tr>`}).join('')}</tbody></table></div>${state.adminDetail?(()=>{const selected=people.find(x=>x.user_id===state.adminDetail);if(!selected)return '';const ps=progressOf(all.filter(a=>a.user_id===selected.user_id));return `<div class="card stack" style="margin-top:10px"><div class="row between"><h3>Radar individual: ${esc(selected.display_name||'Estudante')}</h3><button class="btn outline sm" data-action="detail:clear">Fechar</button></div><div class="grid g3"><div><b>${ps.total}</b><div class="tiny muted">Respostas</div></div><div><b>${ps.rate}%</b><div class="tiny muted">Precisão</div></div><div><b>${ps.xp} XP</b><div class="tiny muted">Pontuação</div></div></div>${subj.map(item=>{const v=ps.by[item.name];return `<div class="stack-tight"><div class="row between"><span>${esc(item.name)}</span><b>${v.pct}% · ${v.total} respostas</b></div><div class="progress"><div style="width:${v.pct}%"></div></div></div>`}).join('')}</div>`})():''}<p class="muted tiny">Ranking e progresso são privados à administração. Os usuários não veem dados uns dos outros.</p></div></div>`)}
function loginPage(){return `<div class="auth-screen"><div class="auth-wrap enter"><div class="auth-art"><div class="logo"><span class="brandmark">${ic('shield',25)}</span><div><div class="brand">FOCO <b>PMMG</b> 2027</div><span class="micro">Disciplina · Constância · Aprovação</span></div></div><div><div class="eyebrow">Sua preparação começa aqui</div><h1>O futuro exige <span>foco.</span></h1><p>Seu espaço de treino, revisão e evolução. Uma questão por vez, um passo mais perto da farda.</p></div><div class="row wrap"><span class="pill">${ic('target',15)} Radar de desempenho</span><span class="pill">${ic('award',15)} XP e missões</span></div></div><div class="auth-panel"><div class="stack-tight"><div class="eyebrow">Acesso exclusivo</div><h2>Bem-vindo de volta.</h2><p class="muted">Entre com as credenciais fornecidas pelo administrador.</p></div>${!configured?`<div class="banner-warning">O acesso real ainda depende de configurar o Supabase exclusivo deste aplicativo. Você pode explorar a prévia local abaixo.</div>`:''}<form id="login-form" class="stack"><div class="field"><label>E-mail</label><input type="email" name="email" autocomplete="username" placeholder="seuemail@exemplo.com" required ${configured?'':'disabled'}></div><div class="field"><label>Senha</label><input type="password" name="password" autocomplete="current-password" placeholder="Sua senha" required ${configured?'':'disabled'}></div><label class="check"><input type="checkbox" name="remember" checked> Manter conectado neste dispositivo</label><button class="btn primary full" type="submit" ${configured?'':'disabled'}>Entrar no Foco PMMG ${ic('arrow',18)}</button></form><button class="btn ghost full" data-action="preview">Explorar demonstração sem conta ${ic('arrow',18)}</button><div class="muted tiny" style="text-align:center">A demonstração é local e não permite criar usuários nem acessar dados reais.</div><p class="muted tiny" style="text-align:center">Sem cadastro público · Dados individuais protegidos · Aplicação não oficial da PMMG</p></div></div></div>`}
// PROVAS ORIGINAIS: visualização do caderno de prova por PDF de terceiro + uma resposta por número.
// Não republicar os enunciados; gabarito oficial separado e anulações preservadas.
const officialDraftKey=()=>`foco_oficial_draft_${state.demo?'demo':state.user?.id||'anon'}`;
function examById(id){return officialExams.find(x=>x.id===id)}
function fmtExamTime(milliseconds){const secs=Math.max(0,Math.floor(milliseconds/1000));return `${String(Math.floor(secs/3600)).padStart(2,'0')}:${String(Math.floor(secs%3600/60)).padStart(2,'0')}:${String(secs%60).padStart(2,'0')}`}
function officialNumbers(mode){return Array.from({length:50},(_,i)=>i+1).filter(n=>mode!=='sem_literatura'||n<21||n>25)}
function officialSubject(n){return n<=20?'Português':n<=25?'Literatura':n<=30?'Inglês':n<=40?'Direito e Direitos Humanos':'Raciocínio Lógico-Matemático'}
function officialGrade(exam,mode,selected){const nums=officialNumbers(mode);let correct=0,wrong=0,blanks=0,annulled=0;for(const n of nums){let expected=exam.answers[n-1],got=selected[String(n)]||'';if(expected===null)annulled++;else if(!got)blanks++;else if(got===expected)correct++;else wrong++}return {total:nums.length,correct,wrong,blanks,annulled,percent:Math.round(correct/(nums.length-annulled)*10000)/100}}
function officialExamHome(){const draft=localStorage.getItem(officialDraftKey());let previous=null;try{previous=JSON.parse(draft)}catch{};return shell(`<div class="stack"><div><div class="eyebrow">COLEÇÃO DE PROVAS REAIS</div><h1 class="headline" style="margin:10px 0">Simulados oficiais</h1><p class="muted">Resolva provas reais de Soldado da PMMG, com 50 itens numerados, tempo de referência de 3 horas e correção pelo gabarito definitivo.</p></div><div class="banner-info">${ic('book',17)} O enunciado original aparece no caderno oficial incorporado abaixo do cartão de respostas. No celular, você também pode abrir o PDF em outra aba. Questões anuladas não entram no cálculo do percentual.</div>${previous&&examById(previous.id)?`<div class="card stack"><div class="eyebrow">VOCÊ TEM UM SIMULADO EM ANDAMENTO</div><h3>${esc(examById(previous.id).title)} · ${previous.mode==='sem_literatura'?'45 itens':'50 itens'}</h3><p class="muted small">Suas respostas estão salvas neste dispositivo.</p>${btn('Continuar de onde parei '+ic('arrow',17),'sim-resume','primary full')}</div>`:''}<div class="official-grid">${officialExams.map(e=>`<div class="card official-exam-card stack"><div class="row between"><span class="tag gold-tag">PROVA REAL · ${e.applicationYear}</span>${ic('award',24)}</div><h2>${esc(e.title)}</h2><p class="muted small">${esc(e.notice)} · 50 questões · 3 horas</p><div class="row wrap"><span class="pill">${ic('book',15)} Gabarito definitivo</span><span class="pill">${e.answers.filter(x=>x===null).length} anuladas</span></div><div class="banner-warning">A prova histórica inclui cinco questões de Literatura sobre os livros daquele edital. Se preferir, você pode pulá-las por enquanto.</div><div class="stack">${btn('Simulado completo · 50 questões','sim-start:'+e.id+':integral','primary full')}${btn('Sem Literatura antiga · 45 questões','sim-start:'+e.id+':sem_literatura','outline full')}</div><div class="row between wrap"><a class="exam-link" href="${esc(e.pdf)}" target="_blank" rel="noopener noreferrer">Caderno original ${ic('arrow',13)}</a><a class="exam-link" href="${esc(e.answerSource)}" target="_blank" rel="noopener noreferrer">Gabarito oficial ${ic('arrow',13)}</a></div></div>`).join('')}</div><div class="card stack"><h3>Seu histórico de simulados</h3>${officialRuns.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Prova</th><th>Data</th><th>Acertos</th><th>Percentual</th><th>Detalhes</th></tr></thead><tbody>${officialRuns.slice(0,12).map((r,i)=>`<tr><td>${esc(examById(r.exam_id)?.title||r.exam_id)} <span class="tiny muted">${r.mode==='sem_literatura'?'sem Literatura':'completo'}</span></td><td>${fmtDate(r.created_at)}</td><td>${r.correct}/${r.total-r.annulled}</td><td>${Number(r.percent).toFixed(1)}%</td><td><button class="btn outline sm" data-action="sim-history:${i}">Revisar</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted small">Seu primeiro simulado aparecerá aqui depois de concluído.</p>'}</div><div class="banner-info">O conteúdo deste módulo é histórico. Quando sair o edital do CFSd 2027, atualizaremos as obras e a estrutura da prova conforme o documento oficial.</div></div>`)}
function officialExamQuestion(){const s=officialSession;if(!s)return officialExamHome();const e=examById(s.id);if(!e)return officialExamHome();const n=s.numbers[s.index],selected=s.selected[String(n)]||'',answered=s.numbers.filter(x=>s.selected[String(x)]).length;return shell(`<div class="stack"><div class="row between wrap"><button class="btn outline sm" data-action="sim-back">${ic('back',15)} Voltar aos simulados</button><span class="pill">${ic('clock',16)} <span id="sim-clock">${fmtExamTime(Date.now()-s.started)}</span></span></div><div class="progress"><div style="width:${Math.round((s.index+1)/s.numbers.length*100)}%"></div></div><div class="row between wrap"><div class="stack-tight"><div class="eyebrow">${esc(e.label)}</div><h1 class="subhead">Questão oficial nº ${n} <span class="muted">· ${s.index+1} de ${s.numbers.length}</span></h1><p class="muted small">${esc(officialSubject(n))} · ${answered}/${s.numbers.length} respostas marcadas</p></div>${e.answers[n-1]===null?badge('Anulada no gabarito final','gold-tag'):badge('Sem correção antecipada')}</div><div class="official-workspace"><div class="card stack official-paper"><div class="row between wrap"><h3>Caderno oficial da PMMG</h3><a class="exam-link" target="_blank" rel="noopener noreferrer" href="${esc(e.pdf)}">Abrir PDF completo ${ic('arrow',14)}</a></div><p class="tiny muted">Procure a questão nº ${n} no PDF abaixo. O documento original mantém textos, tabelas e figuras da prova. A visualização pode depender do navegador.</p><div id="official-pdf-slot"></div><a class="exam-link" target="_blank" rel="noopener noreferrer" href="${esc(e.pdf)}">Se o PDF não carregar, abra o caderno original</a></div><div class="card stack official-answer"><div class="eyebrow">CARTÃO DE RESPOSTAS · Nº ${n}</div><h3>Marque sua alternativa</h3>${['A','B','C','D'].map(ch=>`<button class="optioncard ${selected===ch?'chosen':''}" data-action="sim-answer:${ch}" aria-pressed="${selected===ch}"><span class="letter">${ch}</span><b>Alternativa ${ch}</b>${selected===ch?ic('check',19):''}</button>`).join('')}<button class="btn outline full sm" data-action="sim-clear">Deixar em branco</button><div class="row between wrap"><button class="btn outline sm" data-action="sim-prev" ${s.index===0?'disabled':''}>${ic('back',16)} Anterior</button><button class="btn primary sm" data-action="sim-next" ${s.index===s.numbers.length-1?'disabled':''}>Próxima ${ic('arrow',16)}</button></div><div><p class="muted tiny">Ir diretamente à questão:</p><div class="official-nav-grid">${s.numbers.map((i,pos)=>`<button data-action="sim-jump:${pos}" class="official-nav-number ${pos===s.index?'current':''} ${s.selected[String(i)]?'answered':''}" title="Questão ${i}">${i}</button>`).join('')}</div></div><button class="btn primary full" data-action="sim-finish">${ic('check',17)} Finalizar e corrigir prova</button><p class="tiny muted">Você pode sair e continuar depois. Suas respostas ficam salvas até a finalização.</p></div></div></div>`)}
function officialExamResult(){const d=officialResultData;if(!d)return officialExamHome();const e=examById(d.exam_id);if(!e)return officialExamHome();const nums=officialNumbers(d.mode);let selected=d.selected||{};return shell(`<div class="stack official-results"><div class="card stack"><div class="row between wrap"><span class="tag gold-tag">SIMULADO CONCLUÍDO</span>${ic('award',32)}</div><div class="eyebrow">${esc(e.title)}</div><h1 class="headline">${Number(d.percent).toFixed(1)}% de acertos</h1><p class="muted">${d.mode==='sem_literatura'?'Versão reduzida sem as cinco questões das obras antigas.':'Versão integral, com as cinco questões de Literatura.'} Questões anuladas foram desconsideradas no percentual.</p><div class="grid g3"><div class="card stat"><div class="number">${d.correct}</div><div class="muted">Acertos</div></div><div class="card stat"><div class="number">${d.wrong}</div><div class="muted">Erros</div></div><div class="card stat"><div class="number">${d.blanks}</div><div class="muted">Em branco</div></div></div><div class="muted small">${d.annulled} anuladas · ${d.total} itens apresentados · ${d.total-d.annulled} válidos. ${d.id?'Resultado sincronizado.':'Demonstração: resultado salvo apenas neste navegador.'}</div></div><div class="card stack"><h3>Revisão do seu cartão de respostas</h3><div class="official-review-grid">${nums.map(n=>{let correct=e.answers[n-1],answer=selected[String(n)]||'',status=correct===null?'annulled':!answer?'blank':answer===correct?'right':'wrong';return `<div class="official-review-item ${status}"><b>Q${n}</b><small>${answer||'—'} ${correct===null?'Anulada':correct?'→ '+correct:''}</small></div>`}).join('')}</div><p class="muted tiny">✓ Acerto · ✕ Erro · — Em branco · Anulada conforme gabarito definitivo.</p><div class="row wrap"><a href="${esc(e.pdf)}" target="_blank" rel="noopener noreferrer" class="btn outline">Caderno original ${ic('arrow',16)}</a><a href="${esc(e.answerSource)}" target="_blank" rel="noopener noreferrer" class="btn outline">Gabarito final ${ic('arrow',16)}</a></div><div class="banner-info">${esc(e.note)}</div></div>${btn(ic('calendar',18)+' Outros simulados','sim-back','primary full')}</div>`)}
function saveOfficialDraft(){if(officialSession)localStorage.setItem(officialDraftKey(),JSON.stringify(officialSession))}
async function officialAction(action){
if(action==='sim-back'){officialSession=null;state.screen='simulados';render();return}
if(action.startsWith('sim-history:')){const d=officialRuns[Number(action.slice(12))];if(!d)return;officialResultData=d;state.screen='officialResult';render();return}
if(action==='sim-resume'){let s;try{s=JSON.parse(localStorage.getItem(officialDraftKey())||'null')}catch{};if(!s||!examById(s.id)||!['integral','sem_literatura'].includes(s.mode))throw Error('Não foi possível recuperar esse simulado');officialSession=s;officialSession.numbers=officialNumbers(s.mode);state.screen='officialQuestion';render();return}
if(action.startsWith('sim-start:')){const parts=action.split(':');const ex=examById(parts[1]),mode=parts[2];if(!ex||!['integral','sem_literatura'].includes(mode))return;if(localStorage.getItem(officialDraftKey())&&!window.confirm('Começar outro simulado? O treino anterior em andamento será substituído.'))return;officialSession={id:ex.id,mode,index:0,started:Date.now(),selected:{},numbers:officialNumbers(mode)};saveOfficialDraft();state.screen='officialQuestion';render();return}
const s=officialSession;if(!s)return;const q=s.numbers[s.index];
if(action.startsWith('sim-answer:')){s.selected[String(q)]=action.slice(11);saveOfficialDraft();render();return}
if(action==='sim-clear'){delete s.selected[String(q)];saveOfficialDraft();render();return}
if(action==='sim-prev'&&s.index>0){s.index--;saveOfficialDraft();render();return}
if(action==='sim-next'&&s.index<s.numbers.length-1){s.index++;saveOfficialDraft();render();return}
if(action.startsWith('sim-jump:')){const p=Number(action.slice(9));if(Number.isInteger(p)&&p>=0&&p<s.numbers.length){s.index=p;saveOfficialDraft();render()}return}
if(action==='sim-finish'){
const answered=s.numbers.filter(n=>s.selected[String(n)]).length;const missing=s.numbers.length-answered;
if(!window.confirm(`Finalizar e corrigir ${examById(s.id).title}? ${missing} questões estão em branco. Essa tentativa será registrada.`))return;
const e=examById(s.id);let data;
if(state.demo){data={...officialGrade(e,s.mode,s.selected),exam_id:s.id,mode:s.mode,selected:{...s.selected},created_at:new Date().toISOString(),user_id:'demo'};officialRuns.unshift(data);localStorage.setItem('foco_simulados_demo_results',JSON.stringify(officialRuns));}
else {const result=await req('/rest/v1/rpc/finish_official_exam',{method:'POST',body:JSON.stringify({p_exam_id:s.id,p_mode:s.mode,p_selected:s.selected})});data={...result,exam_id:s.id,mode:s.mode,selected:{...s.selected},created_at:new Date().toISOString(),user_id:state.user.id};officialRuns.unshift(data);if(isAdmin())await loadAdminData()}
officialResultData=data;officialSession=null;localStorage.removeItem(officialDraftKey());state.screen='officialResult';render();return;
}}

function welcome(){return shell(`<div class="train-layout"><div class="card stack" style="padding:35px"><div class="micro">Primeiro acesso</div><h1 class="headline">Como você prefere ser chamado?</h1><p class="muted">Vamos personalizar a sua experiência e suas mensagens diárias.</p><form id="welcome-form" class="stack"><div class="field"><label>Seu nome ou apelido</label><input name="name" maxlength="60" minlength="2" required placeholder="Como devo te chamar?"></div><button class="btn primary full" type="submit">Começar minha preparação ${ic('arrow',17)}</button></form></div></div>`)}
function render(){clearInterval(timer);const map={home,train,question,result,subjects,simulados:officialExamHome,officialQuestion:officialExamQuestion,officialResult:officialExamResult,review,stats:radar,admin,welcome};const currentPaper=app.querySelector('#official-pdf');if(currentPaper)currentPaper.remove();app.innerHTML=state.screen==='login'?loginPage():(map[state.screen]||home)();if(state.screen==='officialQuestion'&&officialSession){const target=app.querySelector('#official-pdf-slot');if(target){let iframe=currentPaper?.dataset.exam===officialSession.id?currentPaper:null;if(!iframe){const paper=officialExams.find(x=>x.id===officialSession.id);iframe=document.createElement('iframe');iframe.id='official-pdf';iframe.dataset.exam=paper.id;iframe.title='Caderno original de questões da PMMG';iframe.loading='lazy';iframe.src=paper.pdf+'#page='+paper.pdfFirstQuestionPage;}target.appendChild(iframe);}}if(state.screen==='officialQuestion'){timer=setInterval(()=>{const el=qs('#sim-clock');if(el&&officialSession)el.textContent=fmtExamTime(Date.now()-officialSession.started)},1000)}document.title=`Foco PMMG 2027 · ${state.screen==='login'?'Entrar':'Minha preparação'}`;bindForms()}
function bindForms(){const lf=qs('#login-form');if(lf)lf.onsubmit=async(e)=>{e.preventDefault();const fd=new FormData(lf);const b=lf.querySelector('[type=submit]');b.disabled=true;b.textContent='Entrando...';try{await login(String(fd.get('email')).trim(),String(fd.get('password')),Boolean(fd.get('remember')))}catch(err){toast('Não foi possível entrar: '+err.message);b.disabled=false;b.textContent='Entrar no Foco PMMG'}};const wf=qs('#welcome-form');if(wf)wf.onsubmit=async e=>{e.preventDefault();try{await saveName(new FormData(wf).get('name'))}catch(err){toast(err.message)}};const af=qs('#create-user');if(af)af.onsubmit=async e=>{e.preventDefault();if(!isAdmin()||state.demo)return;const fd=new FormData(af);const obj={action:'create',name:String(fd.get('name')),email:String(fd.get('email')),password:String(fd.get('password'))};const button=af.querySelector('[type=submit]');button.disabled=true;try{await adminAction(obj);await loadAdminData();render();toast('Usuário criado com sucesso. Envie as credenciais em canal seguro.')}catch(err){toast('Não foi possível criar: '+err.message);button.disabled=false}}}
async function adminAction(obj){if(state.demo)throw Error('Indisponível na prévia');const response=await req(`/functions/v1/${C.functionName||'manage-users'}`,{method:'POST',body:JSON.stringify(obj)});return response}
async function dispatch(action){if(!action)return;try{if(action.startsWith('sim-')){await officialAction(action);return;}if(action==='logout'){logout();return}if(action.startsWith('detail:')){if(!isAdmin())return;state.adminDetail=action.slice(7)==='clear'?null:action.slice(7);render();return}if(action==='preview'){await startDemo();return}if(action.startsWith('nav:')){switchScreen(action.slice(4));return}if(action.startsWith('total:')){selection={...selection,total:Number(action.split(':')[1])};render();return}if(action.startsWith('subject:')){selection={...selection,subject:action.slice(8)};render();return}if(action.startsWith('mode:')){selection={...selection,mode:action.slice(5)};render();return}if(action==='begin'){begin();return}if(action.startsWith('practice:')){selection={total:10,mode:'inteligente',subject:action.slice(9)};begin();return}if(action==='start-errors'){selection={total:10,subject:'Todas as matérias',mode:'erros'};begin();return}if(action.startsWith('single:')){const q=state.questions.find(x=>x.id===action.slice(7));if(q){state.training={queue:[q],index:0,selected:null,confirmed:false,correct:0,earned:0};state.screen='question';render()}return}if(action.startsWith('answer:')){if(state.training&&!state.training.confirmed){state.training.selected=Number(action.slice(7));render()}return}if(action==='confirm'){await confirm();return}if(action==='next'){next();return}if(action==='end'){state.screen='result';render();return}if(action.startsWith('bookmark:')){const id=action.slice(9),exists=state.bookmarks.includes(id);if(state.demo){state.bookmarks=exists?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];localStorage.setItem('foco_demo_bookmarks',JSON.stringify(state.bookmarks))}else{if(exists){await req(`/rest/v1/bookmarks?question_id=eq.${encodeURIComponent(id)}`,{method:'DELETE'});state.bookmarks=state.bookmarks.filter(x=>x!==id)}else{await req('/rest/v1/bookmarks',{method:'POST',body:JSON.stringify({user_id:state.user.id,question_id:id})});state.bookmarks.push(id)}}render();return}if(action.startsWith('report:')){const id=action.slice(7),detail=prompt('Descreva o problema encontrado nesta questão (sem dados pessoais):');if(!detail?.trim())return;if(state.demo){toast('Relatos só podem ser enviados com login real.')}else{await req('/rest/v1/reports',{method:'POST',body:JSON.stringify({question_id:id,user_id:state.user.id,details:detail.trim().slice(0,800)})});toast('Relato enviado para a administração.')}return}if(action.startsWith('disable:')||action.startsWith('enable:')){if(!isAdmin())return;const [verb,id]=action.split(':');if(!window.confirm(verb==='disable'?'Deseja desativar este acesso?':'Deseja reativar este acesso?'))return;await adminAction({action:verb,id});await loadAdminData();render();toast('Acesso atualizado.');return}}catch(err){console.error(err);toast('Ocorreu um problema: '+err.message)}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b){e.preventDefault();dispatch(b.getAttribute('data-action'))}});
async function bootstrap(){try{const stored=localStorage.getItem(storeKey)||sessionStorage.getItem(storeKey);if(configured&&stored){state.session=JSON.parse(stored);state.user=state.session.user;state.remember=state.session.remember;if((state.session.expires_at||0)<Math.floor(Date.now()/1000)+60)await refreshSession();await loadProfileAndData();state.screen=state.profile?.onboarded?'home':'welcome'}}catch(err){console.warn('Não foi possível restaurar sessão',err);localStorage.removeItem(storeKey);sessionStorage.removeItem(storeKey);state.screen='login'}render();if('serviceWorker'in navigator&&!location.protocol.startsWith('file'))navigator.serviceWorker.register('./sw.js').catch(()=>{})}
bootstrap();